css:
@page {
    size: A4;
    margin: 1cm;
}

.head{
    text-align:center;
    color:black;
    padding:15px;
    font-family: Arial, sans-serif;
    font-weight:bold;

}

.receipt {
    font-family: Arial, sans-serif;
    color: black;
    padding: 15px;
}

.receipt-title {
    text-align: center;
    margin-bottom: 25px;
}

h3 {
    margin-top: 25px;
}

.details {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 15px;
}

.details th,
.details td {
    border: 1px solid black;
    padding: 10px;
    text-align: left;
}

.details th {
    width: 45%;
}

.credits {
    font-size: 26px;
    font-weight: bold;
}

.expired-banner {
    border: 2px solid black;
    color: black;
    text-align: center;
    font-size: 22px;
    font-weight: bold;
    padding: 10px;
}

.print-summary {
    margin-top: 30px;
    text-align: center;
    font-size: 16px;
    font-weight: bold;
}
@media print {
    button,
    .no-print {
        display: none !important;
    }
}
